{"actions":[{"type":"success_contract","objective":"Run Windows 3.11 for Workgroups in QEMU from /app/isos/win311.img in snapshot mode, expose VNC on :1/5901, provide nginx web access on port 80, and leave the VM running at the Windows 3.11 desktop with programmatic keyboard input enabled.","required_artifacts":["QEMU launch/configuration command or script","nginx configuration or web entrypoint","runtime evidence showing QEMU/VNC/nginx are running"],"required_behaviors":["QEMU uses /app/isos/win311.img in snapshot mode","VNC listens on display :1 / port 5901","nginx listens on port 80","VM remains running in background","QEMU is configured for programmatic keyboard input beyond VNC-only interaction"],"known_invalid_patterns":["Only proving files exist without runtime behavior","Only proving QEMU starts without confirming VNC/nginx ports","Only proving VNC access without snapshot mode or keyboard-control configuration","Treating prompt echo or non-empty output as success"],"verification_plan":["Inspect available files and environment","Create or locate a launch script/config for QEMU and nginx","Start services in background","Verify listening ports and process state with receipts","If possible, verify QEMU monitor/keyboard-control interface is enabled"],"finalization_evidence_required":["Receipt-backed evidence of QEMU running with the requested image in snapshot mode","Receipt-backed evidence of VNC on port 5901","Receipt-backed evidence of nginx on port 80","Receipt-backed evidence that keyboard-control interface is configured","Receipt-backed evidence that the VM is left running in the background"]},{"type":"plan_update","plan":{"status":"execution","steps":["Inspect filesystem for existing VM/QEMU/nginx assets","Create or adjust launch/configuration artifacts if needed","Start QEMU and nginx in background","Verify ports/processes and capture receipts","Finalize only when evidence matches the original request"]}},{"type":"working_checklist","items":["Find or create QEMU launch command using /app/isos/win311.img","Ensure snapshot mode and VNC :1 / 5901","Add programmatic keyboard control interface","Configure nginx on port 80 for remote access","Start services in background and verify with receipts"]}]}
{"actions":[{"type":"raw_bash","command":"set -euo pipefail
printf 'PWD=%s\n' "$PWD"
find /app -maxdepth 3 \( -name '*.sh' -o -name '*.conf' -o -name 'nginx*' -o -name 'qemu*' -o -name '*.service' \) | sort | sed -n '1,200p'","timeout_seconds":30}]}
